package com.rescuefarm.ui.engagement;import android.Manifest;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.annotation.*;import androidx.core.content.ContextCompat;import androidx.fragment.app.Fragment;import androidx.lifecycle.ViewModelProvider;import androidx.navigation.*;import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.messaging.FirebaseMessaging;import com.rescuefarm.R;import com.rescuefarm.domain.model.Notification;import com.rescuefarm.service.engagement.NotificationDeepLinkService;import java.util.*;
public class NotificationFragment extends Fragment{private EngagementViewModel vm;private LinearLayout box;private String uid="";private final androidx.activity.result.ActivityResultLauncher<String> permission=registerForActivityResult(new ActivityResultContracts.RequestPermission(),granted->{if(!granted)Toast.makeText(requireContext(),R.string.notification_permission_denied,Toast.LENGTH_LONG).show();});@Nullable public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup p,@Nullable Bundle s){return i.inflate(R.layout.fragment_notifications,p,false);}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle s){uid=FirebaseAuth.getInstance().getCurrentUser()==null?"":FirebaseAuth.getInstance().getCurrentUser().getUid();box=v.findViewById(R.id.notificationContainer);vm=new ViewModelProvider(this,new EngagementViewModelFactory(requireContext())).get(EngagementViewModel.class);vm.notifications().observe(getViewLifecycleOwner(),this::render);vm.getState().observe(getViewLifecycleOwner(),x->{if(x.getStatus()==EngagementState.Status.ERROR)Toast.makeText(requireContext(),x.getMessage(),Toast.LENGTH_LONG).show();});v.findViewById(R.id.enableNotificationsButton).setOnClickListener(x->enable());vm.refreshNotifications(uid);}private void enable(){if(Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(requireContext(),Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)permission.launch(Manifest.permission.POST_NOTIFICATIONS);FirebaseMessaging.getInstance().getToken().addOnSuccessListener(t->vm.registerToken(uid,t)).addOnFailureListener(e->Toast.makeText(requireContext(),R.string.fcm_token_failed,Toast.LENGTH_LONG).show());}private void render(List<Notification>xs){box.removeAllViews();if(xs==null||xs.isEmpty()){TextView t=new TextView(requireContext());t.setText(R.string.notifications_empty);box.addView(t);return;}for(Notification n:xs){Button b=new Button(requireContext());b.setAllCaps(false);b.setText((n.isRead()?"":"● ")+n.getTitle()+"\n"+n.getBody());b.setOnClickListener(v->{vm.markRead(n.getId(),uid);String link=new NotificationDeepLinkService().build(n.getType(),n.getReferenceId());try{Navigation.findNavController(requireView()).navigate(NavDeepLinkRequest.Builder.fromUri(Uri.parse(link)).build());}catch(Exception e){Toast.makeText(requireContext(),R.string.deep_link_unavailable,Toast.LENGTH_SHORT).show();}});box.addView(b);}}}
